# Lesson 3.2: the style attribute, color, background-color (named and hex colors); chaining; style on body
L = lambda *a: '\n'.join(a)
def P(title, story, code, dis): return (title, story, code, dis)
P32 = [
 P('Color one heading', 'Make the heading Pizza Night tomato red with the color property, and add a paragraph under it that says Fresh and hot.',
   L('<h1 style="color: tomato;">Pizza Night</h1>', '<p>Fresh and hot.</p>'),
   [(0, '<h1 style="color: tomato;">Pizza Night</h1'), (0, '<h1 style=color: tomato;>Pizza Night</h1>'), (0, '<h1 style="colour: tomato;">Pizza Night</h1>')]),
 P('A highlighted paragraph', 'Write a paragraph that says Sale today and give it a yellow background with background-color. Then add a plain paragraph that says Everything must go.',
   L('<p style="background-color: yellow;">Sale today</p>', '<p>Everything must go.</p>'),
   [(0, '<p style="color: yellow;">Sale today</p>'), (0, '<p style="background-color: yellow;">Sale today</p style="background-color: yellow;">'), (0, '<p style="background-color: yelow;">Sale today</p>')]),
 P('Two colors in one style', 'Make the heading Big News white text on a navy background. Put both properties in the same style attribute, each finished with a semicolon.',
   L('<h1 style="color: white; background-color: navy;">', 'Big News', '</h1>'),
   [(0, '<h1 style="color: white background-color: navy;">'), (0, '<h1 style="color: white; background-color: navy;"'), (0, '<h1 style="color: white; background: navy;">')]),
 P('Color the whole page', 'Make the whole page background black by putting a style on the body, and put one white heading that says After Dark inside it.',
   L('<body style="background-color: black;">', '<h1 style="color: white;">After Dark</h1>', '</body>'),
   [(0, '<body style="color: black;">'), (1, '<h1 style="color: white;">After Dark</h1'), (2, '</body style="background-color: black;">')]),
 P('Color names', 'Color the heading Sunset with the color name darkcyan. Under it, give the level 2 heading Golden hour a background-color of the color name lightyellow. HTML knows 140 color names like these.',
   L('<h1 style="color: darkcyan;">Sunset</h1>', '<h2 style="background-color: lightyellow;">Golden hour</h2>'),
   [(0, '<h1 style="color: darkcyan;>Sunset</h1>'), (0, '<h1 style="color: dark cyan;">Sunset</h1>'), (1, '<h2 style="background-color: light yellow;">Golden hour</h2>')]),
 P('Two paragraphs, two colors', 'Write two paragraphs. The first says Roses are red. and is red. The second says Violets are blue. and is blue.',
   L('<p style="color: red;">Roses are red.</p>', '<p style="color: blue;">Violets are blue.</p>'),
   [(0, '<p style="color: rde;">Roses are red.</p>'), (1, '<p style="color: blue;">Violets are blue.'), (0, '<p color: red;>Roses are red.</p>')]),
 P('A colorful outline', 'Build an outline for a page about frogs. The level 1 heading Frogs is green, the level 2 heading Where They Live is dodgerblue, and the paragraph They live near ponds. is brown.',
   L('<h1 style="color: green;">Frogs</h1>', '<h2 style="color: dodgerblue;">Where They Live</h2>', '<p style="color: brown;">They live near ponds.</p>'),
   [(1, '<h2 style="color: dodger blue;">Where They Live</h2>'), (2, '<p style="color: brown;">They live near ponds.</p>;'), (0, '<h1 style="color: green;">Frogs</h2>')]),
 P('Readable on a dark page', 'Make a dark page: the body has a black background, the heading Moon Facts is gold, and the paragraph The moon has no air. is white.',
   L('<body style="background-color: black;">', '<h1 style="color: gold;">Moon Facts</h1>', '<p style="color: white;">The moon has no air.</p>', '</body>'),
   [(0, '<body style="background-color: black;>'), (1, '<h1 style="background-color: gold;">Moon Facts</h1>'), (3, '<body>')]),
 P('A full page with a colored heading', 'Build a full page titled Color Lab. The body has a lightyellow background. Inside it is a heading Color Lab in purple and a paragraph that says Mix and match. in hotpink.',
   L('<!DOCTYPE html>', '<html>', '<head>', '<title>Color Lab</title>', '</head>', '<body style="background-color: lightyellow;">', '<h1 style="color: purple;">Color Lab</h1>', '<p style="color: hotpink;">Mix and match.</p>', '</body>', '</html>'),
   [(5, '<body style="background-color: lightyellow;"'), (6, '<h1 style="color: purple;">Color Lab<h1>'), (7, '<p style="colour: hotpink;">Mix and match.</p>')]),
 P('A full page with two styled sections', 'Build a full page titled Beach Day. The body is lightblue. The heading Beach Day is navy with a white background. The level 2 heading Packing List is teal. The paragraph that says Towel, sunscreen, snacks. is darkgreen.',
   L('<!DOCTYPE html>', '<html>', '<head>', '<title>Beach Day</title>', '</head>', '<body style="background-color: lightblue;">', '<h1 style="color: navy; background-color: white;">Beach Day</h1>', '<h2 style="color: teal;">Packing List</h2>', '<p style="color: darkgreen;">Towel, sunscreen, snacks.</p>', '</body>', '</html>'),
   [(6, '<h1 style="color: navy background-color: white;">Beach Day</h1>'), (7, '<h2 style="color: teal;">Packing List</h2 style="color: teal;">'), (8, '<p style="color: dark green;">Towel, sunscreen, snacks.</p>')]),
]
